class Musica {
    nome : string
    artista : number
    duracao: number
    genero : number

    constructor(nome : string, artista : number, duracao: number, genero : number) {
        this.nome === nome
        this.duracao ===  duracao
        this.genero === genero
        this.artista === artista
    }
}

function constructor(m1 : Musica, m2 : Musica) : Musica {
    return m1.duracao > m2.duracao;
}

class AM {
    o : string = ""
    y : string = ""
}

function single(aa : AM) {
    let t : string = ""
    let m : string = ""

    for (let i = 0; i < aa.o.length; i++) {
        t = t + aa.o[i]
        m = m + aa.y[i]
    }

    aa.o = m
    aa.y = t
}

let aa : AM = { o : "efive", y : "givem"}
single(aa)
console.log(aa.o + aa.y)
